import{_ as l,I as e,g as o,j as r}from"./chunks/framework.CjoWWfVe.js";const p=JSON.parse('{"title":"Сырьё (Склад материалов)","description":"Как работает партионный учет, логистика и MAC-себестоимость сырья в ОмниКрафт ЕРП.","frontmatter":{"title":"Сырьё (Склад материалов)","description":"Как работает партионный учет, логистика и MAC-себестоимость сырья в ОмниКрафт ЕРП.","order":5},"headers":[],"relativePath":"ru/docs/spaces/production/warehouse.md","filePath":"ru/docs/spaces/production/warehouse.md"}'),s={name:"ru/docs/spaces/production/warehouse.md"};function a(n,t,i,d,g,c){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="📦-сырье-склад-материалов-и-партионные-закупки" tabindex="-1">📦 Сырьё: Склад материалов и партионные закупки <a class="header-anchor" href="#📦-сырье-склад-материалов-и-партионные-закупки" aria-label="Permalink to &quot;📦 Сырьё: Склад материалов и партионные закупки&quot;">​</a></h1><p>Вкладка <strong>«Сырьё»</strong> — это сердце логистики вашего ремесленного дела. Здесь хранятся все материалы, которые физически участвуют в производстве изделий: кожа, нитки, клей, фурнитура, ткань, древесина и упаковка.</p><p>ОмниКрафт ЕРП использует профессиональный метод учета себестоимости — <strong>МАК (Moving Average Cost — Скользящая средняя стоимость)</strong>, избавляя вас от необходимости вручную высчитывать, сколько стоит квадратный дециметр кожи с учетом стоимости доставки.</p><hr><h2 id="📋-паспорт-материала" tabindex="-1">📋 Паспорт материала <a class="header-anchor" href="#📋-паспорт-материала" aria-label="Permalink to &quot;📋 Паспорт материала&quot;">​</a></h2><p>Прежде чем купить материал, его нужно добавить в базу (номенклатуру). Нажмите кнопку <strong>«+»</strong> (Новая позиция) в верхней панели.</p><p>В паспорте материала указываются:</p><ul><li><strong>Название:</strong> Например, <em>«Глина кембрийская очищенная (Сухая, порошок)»</em> или <em>«Солома овсяная измельченная (Фракция 2-4 см)»</em>.</li><li><strong>Артикул (Авто):</strong> Уникальный складской номер позиции. Если оставить поле пустым, программа <strong>автоматически присвоит артикул</strong> формата <code>АРТ-0001</code> (например, <code>АРТ-0020</code> для партии глины), обеспечивая сквозной учет при поиске и печати бирок.</li><li><strong>Категория:</strong> Группировка для удобства (например, <em>«Глина»</em>, <em>«Солома и волокна»</em>, <em>«Химия и связующие»</em>). Категории можно редактировать &quot;на лету&quot;, нажав на иконку карандаша.</li><li><strong>Единицы измерения:</strong> В чем вы будете измерять материал в рецептах (дм², шт, мл, метры). <em>Важно: выбирайте ту единицу, в которой вам удобнее считать расход на одно изделие.</em></li><li><strong>Мин. остаток (Порог безопасности):</strong> Значение, при котором остаток в таблице подсветится желтым цветом (предупреждение об исчерпании запаса). <em>💡 Умный авто-расчет:</em> Если оставить это поле равным <code>0</code>, программа будет <strong>динамически вычислять порог сама</strong> (по умолчанию 20% от среднего объема ваших последних 20 закупок этого сырья). Штучные товары при этом разумно округляются до целых чисел. Изменить целевой процент или полностью отключить авто-расчет можно в Настройках вкладки (иконка ⚙️ в верхнем меню).</li></ul><h3 id="🔗-управление-ссылками-и-поставщиками" tabindex="-1">🔗 Управление ссылками и поставщиками <a class="header-anchor" href="#🔗-управление-ссылками-и-поставщиками" aria-label="Permalink to &quot;🔗 Управление ссылками и поставщиками&quot;">​</a></h3><p>Если вы нажмете на иконку «Редактировать» (✏️) рядом с материалом, откроется его расширенный паспорт. Там вы можете привязать к сырью сразу несколько ссылок на одного или разных поставщиков (например, добавить оптовую и розничную ссылку на закупку одного и того же сорта глины).</p><p>Чтобы не перегружать главную таблицу склада лишней информацией, управление ссылками работает по принципу адаптивного интерфейса:</p><ul><li>⭐ <strong>«Показывать в таблице»:</strong> Базовый статус. В главной таблице все такие поставщики будут аккуратно свернуты в бейдж <code>(+N)</code>. При клике на него откроется окно со списком ссылок для быстрого перехода. Если снять звездочку, ссылка уйдет в запас (станет серой) и скроется из таблицы, но останется доступна при проведении новых закупок.</li><li>📌 <strong>«Закрепить»:</strong> Поднимает выбранную ссылку на самый верх списка среди остальных активных.</li><li>✅ <strong>«Сделать главным»:</strong> Эта радиокнопка появляется, если вы закрепили булавкой несколько ссылок. Она позволяет выбрать ту самую <em>единственную</em> ссылку, которая будет открыто отображаться в ячейке главной таблицы склада. При клике на её название сайт поставщика откроется мгновенно.</li></ul><hr><h2 id="🛒-партионная-закупка-и-логистика" tabindex="-1">🛒 Партионная закупка и логистика <a class="header-anchor" href="#🛒-партионная-закупка-и-логистика" aria-label="Permalink to &quot;🛒 Партионная закупка и логистика&quot;">​</a></h2><p>Главная «магия» ОмниКрафт ЕРП кроется в кнопке <strong>«Партионная закупка»</strong> (иконка корзины в верхнем меню). Никогда не вносите купленные материалы через инвентаризацию — используйте закупку!</p><h3 id="как-работает-умное-распределение-доставки" tabindex="-1">Как работает умное распределение доставки: <a class="header-anchor" href="#как-работает-умное-распределение-доставки" aria-label="Permalink to &quot;Как работает умное распределение доставки:&quot;">​</a></h3><p>Допустим, вы заказали у поставщика:</p><ol><li>Мешок кембрийской глины за 5 000 ₽</li><li>Тюк овсяной соломы за 1 000 ₽</li><li>И заплатили за доставку транспортной компании 600 ₽.</li></ol><p>Если вы просто разделите 600 ₽ доставки пополам (по 300 ₽ на позицию), себестоимость дешевой соломы взлетит до небес, что сильно исказит цену готовых изделий.</p><p><strong>ОмниКрафт ЕРП распределяет доставку пропорционально стоимости товаров:</strong></p><ul><li>Глина (5000 ₽) заберет на себя 500 ₽ доставки.</li><li>Солома (1000 ₽) заберет всего 100 ₽ доставки. Программа сделает эту математику за доли секунды и запишет на склад правильную, справедливую себестоимость каждой позиции.</li></ul><h3 id="что-происходит-при-проведении-закупки" tabindex="-1">Что происходит при проведении закупки: <a class="header-anchor" href="#что-происходит-при-проведении-закупки" aria-label="Permalink to &quot;Что происходит при проведении закупки:&quot;">​</a></h3><ol><li>На склад зачисляется физическое количество материалов.</li><li>Программа пересчитывает <strong>средневзвешенную цену</strong>. Если у вас оставалась глина по старой цене, а вы купили новую партию по более дорогой, программа автоматически усреднит их стоимость.</li><li>В журнале <strong>ДДС</strong> автоматически создаются две записи расходов: <em>«Закупка сырья»</em> (на 6 000 ₽) и <em>«Доставка сырья»</em> (на 600 ₽).</li></ol><hr><h2 id="🖨️-маркировка-склада-и-печать-бирок" tabindex="-1">🖨️ Маркировка склада и печать бирок <a class="header-anchor" href="#🖨️-маркировка-склада-и-печать-бирок" aria-label="Permalink to &quot;🖨️ Маркировка склада и печать бирок&quot;">​</a></h2><p>Программа имеет встроенный 100% автономный генератор этикеток, поддерживающий как термопринтеры (рулоны), так и обычные офисные принтеры (листы А4 с самоклейкой). Вы можете печатать бирки поштучно из карточки материала (кнопка <strong>«Печать бирки»</strong>) или массово для всего стеллажа, нажав <strong>«Пакетная печать бирок»</strong> в верхней панели склада.</p><h3 id="режимы-кодирования-что-на-бирке" tabindex="-1">Режимы кодирования (Что на бирке) <a class="header-anchor" href="#режимы-кодирования-что-на-бирке" aria-label="Permalink to &quot;Режимы кодирования (Что на бирке)&quot;">​</a></h3><p>В зависимости от размера этикетки, вы можете разместить на ней один или несколько полезных кодов:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Режим</th><th style="text-align:left;">Как работает</th><th style="text-align:left;">Практический пример</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Артикул</strong></td><td style="text-align:left;">Линейный штрихкод (Code128).</td><td style="text-align:left;">Вы наводите сканер на банку с соломой ➔ программа мгновенно находит её на складе.</td></tr><tr><td style="text-align:left;"><strong>Заказ у поставщика</strong></td><td style="text-align:left;">QR-код с прямой ссылкой на магазин.</td><td style="text-align:left;">Навели камеру телефона на полку с маслом-разделителем ➔ на экране открылся сайт для дозаказа. Если поставщиков несколько, откроется удобный список.</td></tr><tr><td style="text-align:left;"><strong>Паспорт материала</strong></td><td style="text-align:left;">QR-код с текстовыми характеристиками.</td><td style="text-align:left;">Навели телефон на коробку с глиной на верхней полке ➔ на экране крупно показан остаток и локация без интернета.</td></tr><tr><td style="text-align:left;"><strong>Артикул + Заказ</strong></td><td style="text-align:left;">Комбинированный режим (штрихкод внизу, QR сбоку).</td><td style="text-align:left;">Идеально для средних наклеек (от 58×40 мм).</td></tr><tr><td style="text-align:left;"><strong>Артикул + Заказ + Паспорт</strong></td><td style="text-align:left;">Трио-Макси: штрихкод и два QR-кода.</td><td style="text-align:left;">Для крупных коробов и поддонов (от 100×75 мм).</td></tr><tr><td style="text-align:left;"><strong>Только текст</strong></td><td style="text-align:left;">Крупный читаемый шрифт без кодов.</td><td style="text-align:left;">Для самых маленьких баночек (30×20 мм).</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">🧠 Умные подписи (Адаптивная компоновка)</p><p>Если вы выбрали печать «Поставщики + Паспорт» (с двумя QR-кодами) для партии овсяной соломы или сухой глины, но в карточке материала не указана ссылка на интернет-магазин поставщика, программа проявит заботу. Она на лету перестроит этикетку и напечатает только один крупный QR-код с текстовым Паспортом. Это экономит место на наклейке, улучшает читаемость и защищает вас от сканирования бессмысленных дубликатов.</p></div><h3 id="🎛️-настроики-печати-рамки-и-калибровка" tabindex="-1">🎛️ Настройки печати (Рамки и Калибровка) <a class="header-anchor" href="#🎛️-настроики-печати-рамки-и-калибровка" aria-label="Permalink to &quot;🎛️ Настройки печати (Рамки и Калибровка)&quot;">​</a></h3><p>При печати вы можете выбрать тип <strong>Окантовки / Рамки</strong>:</p><ul><li><strong>Без рамки:</strong> Идеально для готовой заводской самоклеящейся бумаги с вырубкой (например, Lomond). Отсутствие рамки гарантирует, что при микро-перекосе листа принтером черные линии не «залезут» на соседние этикетки.</li><li><strong>Пунктир (для реза):</strong> Используется при печати на обычных листах А4 для удобного вырезания ножницами или дисковым ножом.</li><li><strong>Сплошная рамка:</strong> Декоративный контур, отлично смотрится на крафтовом картоне при печати навесных бирок для изделий.</li></ul><div class="tip custom-block"><p class="custom-block-title">🛠️ Калибровка принтера (Компенсация смещения)</p><p>При печати на листах А4 ролики захвата бумаги могут сдвигать печать вниз на 3–5 мм, а на рулонных термопринтерах оптический датчик зазора или люфт ленты могут давать смещение на 1–2 мм.</p><p>Чтобы макет попадал в наклейку со 100% точностью на любом оборудовании, используйте блок <strong>Калибровка принтера (мм)</strong>:</p><ul><li><strong>Сдвиг Y (мм):</strong> смещает печать по вертикали (например, <code>-3.0</code> поднимет макет вверх на 3 мм).</li><li><strong>Сдвиг X (мм):</strong> смещает печать по горизонтали (влево/вправо).</li></ul><p>Выставите нужные значения один раз — программа автоматически сохранит их для всех последующих тиражей.</p></div><div class="tip custom-block"><p class="custom-block-title">📱 Смартфон вместо сканера</p><p>Вам не обязательно покупать дорогой USB-сканер. Вы можете установить на свой телефон бесплатное приложение (например, Barcode to PC или любой Bluetooth эмулятор клавиатуры). Телефон будет считывать штрихкоды и мгновенно «впечатывать» артикулы в строку поиска ОмниКрафт ЕРП на вашем компьютере.</p></div><hr><h2 id="⚖️-инвентаризация-корректировка-остатков" tabindex="-1">⚖️ Инвентаризация (Корректировка остатков) <a class="header-anchor" href="#⚖️-инвентаризация-корректировка-остатков" aria-label="Permalink to &quot;⚖️ Инвентаризация (Корректировка остатков)&quot;">​</a></h2><p>Кнопка <strong>«Инвентаризация»</strong> (иконка весов) используется <strong>только</strong> для исправления физических расхождений на складе.</p><p>Например, программа показывает, что у вас осталось 15 кг глины, а по факту она засохла и из нее уже ничего не слепить. Вы проводите инвентаризацию и списываете недостачу.</p><ul><li><strong>Финансовая безопасность:</strong> Инвентаризация <strong>НЕ трогает</strong> ваши деньги (ДДС) и Баланс. Она лишь списывает физическое количество, чтобы программа не позволяла вам планировать производство из несуществующих материалов.</li></ul><hr><h2 id="🗄️-архивирование-и-удаление" tabindex="-1">🗄️ Архивирование и удаление <a class="header-anchor" href="#🗄️-архивирование-и-удаление" aria-label="Permalink to &quot;🗄️ Архивирование и удаление&quot;">​</a></h2><p>Если вы перестали работать с определенным материалом (например, поставщик перестал привозить эту краску), вы можете отправить его в <strong>Архив</strong> (красная кнопка с коробкой).</p><ul><li>Материал исчезнет из активного списка и перестанет мешаться при поиске.</li><li>При переносе в архив программа предложит <strong>обнулить остатки</strong> этого материала, если они там были.</li><li>Заархивированный материал можно вернуть в любой момент, перейдя на вкладку «В архиве».</li></ul><div class="warning custom-block"><p class="custom-block-title">Блокировка архивации</p><p>Вы не сможете отправить материал в архив, если он прямо сейчас используется хотя бы в одном рецепте (в Калькуляторе) или если на верстаке есть незаконченный заказ, требующий этот материал. Программа выведет окно с точным списком изделий, которые блокируют перенос. Сперва нужно будет изменить рецепты.</p></div><hr><h2 id="⚙️-настроики-вкладки-сырье" tabindex="-1">⚙️ Настройки вкладки Сырьё <a class="header-anchor" href="#⚙️-настроики-вкладки-сырье" aria-label="Permalink to &quot;⚙️ Настройки вкладки Сырьё&quot;">​</a></h2><p>Для кастомизации интерфейса под ваши нужды нажмите иконку <strong>Настройки вкладки Сырьё</strong> (ползунки) в верхней панели.</p><ul><li><strong>Отображение колонок:</strong> Скрывайте лишние столбцы (например, Артикул или Локацию), чтобы освободить место на экране.</li><li><strong>Отображение кнопок действий в таблице:</strong> Вы можете гибко включать и отключать иконки быстрых действий для каждой строки (<em>Закупка сырья, Инвентаризация, Печать бирки, Редактирование, Архивация / Удаление</em>). Оставьте только те, которыми пользуетесь ежедневно, чтобы предотвратить случайные клики.</li><li><strong>Автоматический расчет минимального остатка:</strong> Настройте процент для динамического порога дефицита (подробнее в разделе «Паспорт материала»).</li></ul><hr><h2 id="↩️-отмена-операции-сторно" tabindex="-1">↩️ Отмена операций (Сторно) <a class="header-anchor" href="#↩️-отмена-операции-сторно" aria-label="Permalink to &quot;↩️ Отмена операций (Сторно)&quot;">​</a></h2><p>Если вы ошиблись при закупке или инвентаризации, операцию можно отменить прямо из <strong>Журнала операций</strong> или паспорта материала.</p><ol><li>Нажмите на иконку <strong>Отмены (↩️)</strong> рядом с ошибочной операцией.</li><li>Программа автоматически создаст корректирующую запись (<strong>Сторно</strong>), которая вернет физический остаток на складе к прежнему значению.</li><li>Если отменяется закупка с указанной ценой или доставкой, потраченные средства автоматически вернутся в кассу ДДС.</li></ol><div class="warning custom-block"><p class="custom-block-title">Ограничения отмены</p><ul><li><strong>Защита метода МАК (Исторические закупки):</strong> Вы не сможете отменить закупку, если после неё уже проводились другие операции, изменившие остаток этого сырья. Это необходимо для защиты средневзвешенной цены. Чтобы отменить старую закупку, сначала придется отменить все более новые операции с этим материалом.</li><li><strong>Списания Верстака:</strong> Списания, сделанные при производстве готовых изделий, нельзя отменить через склад сырья. Для их отмены перейдите во вкладку «Производство» и отмените соответствующий заказ.</li></ul></div>',54)])])}const u=l(s,[["render",a]]);export{p as __pageData,u as default};
